/* TEAM CODE (owner: Jack - audio input and SD storage) - written by the BJT2 team, not generated by STM32CubeMX. */
/* The card's state machine, plus its capacity and file count, and the
 * display-ready snapshot made from them (storage_status.h has the rules).
 *
 * No task of its own: jack_audio_sd.c calls it inside JackStorageTask. It
 * feeds in the facts (card in or out, the mount result, capacity, the file
 * count, a runtime fault, the user's retry) and copies the snapshot into
 * every StorageStatusMsg_t it publishes for TonyTask.
 *
 * card_state_t, from -> to:
 *   ABSENT            -> PRESENT_UNMOUNTED   a card is detected
 *   PRESENT_UNMOUNTED -> READY / FAULT       the mount worked / failed
 *   READY             -> FAULT               a runtime fault (write fail, full,
 *                                            3 slow writes, read fault)
 *   FAULT             -> READY               the user's retry (clear_fault), or a
 *                                            mount that works
 *   any               -> ABSENT              the card is gone: everything cleared
 * Record needs READY; Play needs READY and at least one file.
 * Pure logic, no RTOS or HAL (tests: Tests/test_storage_status.c). */
#include "storage_status.h"

/* Display strings are owned by this module so that every screen in the
 * system shows identical wording for the same condition. */
static const char *const STATUS_TEXT_NO_CARD   = "No Card";
static const char *const STATUS_TEXT_NOT_READY = "Card Not Ready";
static const char *const STATUS_TEXT_READY     = "Ready";
static const char *const STATUS_TEXT_ERROR     = "Card Error";
static const char *const STATUS_TEXT_FULL      = "Card Full";

void storage_status_init(storage_status_t *status)
{
    if (status == NULL)
    {
        return;
    }
    status->state = CARD_ABSENT;
    status->last_fault = STORAGE_OK;
    status->total_kb = 0U;
    status->free_kb = 0U;
    status->file_count = 0U;
}

void storage_status_set_card_detected(storage_status_t *status, bool card_detected)
{
    if (status == NULL)
    {
        return;
    }

    if (!card_detected)
    {
        /* A removed card invalidates capacity, file list and any fault
         * that referred to the old card. */
        storage_status_init(status);
        return;
    }

    if (status->state == CARD_ABSENT)
    {
        status->state = CARD_PRESENT_UNMOUNTED;
        status->last_fault = STORAGE_OK;
    }
    /* Already PRESENT_UNMOUNTED / READY / FAULT: a still-inserted card
     * does not change state just because the pin is re-read. */
}

void storage_status_set_mount_result(storage_status_t *status, storage_result_t result)
{
    if (status == NULL)
    {
        return;
    }
    if (status->state == CARD_ABSENT)
    {
        /* Cannot mount a card that is not there. */
        return;
    }

    if (result == STORAGE_OK)
    {
        status->state = CARD_READY;
        status->last_fault = STORAGE_OK;
    }
    else
    {
        status->state = CARD_FAULT;
        status->last_fault = result;
    }
}

void storage_status_set_capacity(storage_status_t *status, uint32_t total_kb, uint32_t free_kb)
{
    if (status == NULL)
    {
        return;
    }
    status->total_kb = total_kb;
    /* Free space can never exceed total capacity; clamp rather than
     * propagating an impossible figure to the UI. */
    status->free_kb = (free_kb > total_kb) ? total_kb : free_kb;
}

void storage_status_set_file_count(storage_status_t *status, size_t file_count)
{
    if (status == NULL)
    {
        return;
    }
    status->file_count = file_count;
}

void storage_status_report_fault(storage_status_t *status, storage_result_t fault)
{
    if (status == NULL)
    {
        return;
    }
    if (fault == STORAGE_OK)
    {
        return;
    }
    if (status->state == CARD_ABSENT)
    {
        /* No card - absence is already the more specific condition. */
        return;
    }
    status->state = CARD_FAULT;
    status->last_fault = fault;
}

void storage_status_clear_fault(storage_status_t *status)
{
    if (status == NULL)
    {
        return;
    }
    if (status->state == CARD_FAULT)
    {
        status->state = CARD_READY;
        status->last_fault = STORAGE_OK;
    }
}

uint8_t storage_status_percent_used(const storage_status_t *status)
{
    if (status == NULL)
    {
        return 0U;
    }
    if (status->total_kb == 0U)
    {
        return 0U;
    }

    const uint32_t used_kb = status->total_kb - status->free_kb;
    /* Use 64-bit intermediate so large cards cannot overflow the multiply. */
    const uint64_t percent = ((uint64_t)used_kb * 100U) / (uint64_t)status->total_kb;
    return (uint8_t)percent;
}

bool storage_status_can_record(const storage_status_t *status)
{
    if (status == NULL)
    {
        return false;
    }
    return (status->state == CARD_READY);
}

bool storage_status_can_play(const storage_status_t *status)
{
    if (status == NULL)
    {
        return false;
    }
    return (status->state == CARD_READY) && (status->file_count > 0U);
}

storage_result_t storage_status_get_ui_view(const storage_status_t *status,
                                             storage_ui_view_t *out_view)
{
    if ((status == NULL) || (out_view == NULL))
    {
        return STORAGE_INVALID_ARG;
    }

    switch (status->state)
    {
        case CARD_ABSENT:
            out_view->status_text = STATUS_TEXT_NO_CARD;
            break;

        case CARD_PRESENT_UNMOUNTED:
            out_view->status_text = STATUS_TEXT_NOT_READY;
            break;

        case CARD_READY:
            out_view->status_text = STATUS_TEXT_READY;
            break;

        case CARD_FAULT:
        default:
            /* A full card is a distinct, user-actionable condition, so it
             * gets its own wording rather than a generic error. */
            out_view->status_text = (status->last_fault == STORAGE_FULL)
                                        ? STATUS_TEXT_FULL
                                        : STATUS_TEXT_ERROR;
            break;
    }

    out_view->record_enabled = storage_status_can_record(status);
    out_view->play_enabled = storage_status_can_play(status);
    out_view->percent_used = storage_status_percent_used(status);
    out_view->file_count = status->file_count;
    out_view->low_space_warning =
        (status->state == CARD_READY) &&
        (out_view->percent_used >= STORAGE_LOW_SPACE_WARN_PERCENT);

    return STORAGE_OK;
}

uint32_t storage_status_recording_seconds_remaining(const storage_status_t *status,
                                                     uint32_t sample_rate,
                                                     uint16_t bits_per_sample,
                                                     uint16_t num_channels)
{
    if (status == NULL)
    {
        return 0U;
    }
    if ((sample_rate == 0U) || (bits_per_sample == 0U) || (num_channels == 0U))
    {
        return 0U;
    }
    if ((bits_per_sample % 8U) != 0U)
    {
        return 0U;
    }
    if (status->free_kb == 0U)
    {
        return 0U;
    }

    const uint32_t bytes_per_second =
        sample_rate * (uint32_t)num_channels * ((uint32_t)bits_per_sample / 8U);

    if (bytes_per_second == 0U)
    {
        return 0U;
    }

    const uint64_t free_bytes = (uint64_t)status->free_kb * 1024U;
    return (uint32_t)(free_bytes / (uint64_t)bytes_per_second);
}
